/**
 * The unit interval_count counts in.
 */
export type RenewRequestInterval = (typeof RenewRequestInterval)[keyof typeof RenewRequestInterval];

export const RenewRequestInterval = {
  day: "day",
  month: "month",
  year: "year",
} as const;

export interface RenewRequest {
  /** Purchase ID saved before submitting. Duplicate creation conflicts; query this order after an unknown result. */
  order_id: string;
  /**
   * How many further periods to buy, each at the price this item already bills at.
   *
   * Buying twelve monthly periods is not the same as buying one yearly term: a longer
   * term is usually sold at a lower price, and that price is only reached by naming the
   * interval. Use `interval_count` and `interval` for that.
   * @minimum 1
   */
  periods?: number;
  /**
   * Renew for a term of this length instead, at the price currently sold for it. Give
   * `interval` with it.
   *
   * Leaving both out renews at the price this item already bills at, which a later price
   * change does not affect. Naming a term that differs from the current one is a fresh
   * choice, so it is bought at today's price. Naming the current term changes nothing. A
   * term sold at several prices that differ in termination policy is refused with 409
   * `BILLING_RENEWAL_OPTION_AMBIGUOUS` unless `termination_policy` is given.
   *
   * List the terms on offer with the renewal prices operation.
   * @minimum 1
   */
  interval_count?: number;
  /** The unit interval_count counts in. */
  interval?: RenewRequestInterval;
  /** With `interval` and `interval_count`, chooses among prices of that term that differ in termination policy. */
  termination_policy?: TerminationPolicy;
  payment_method_id?: string;
  /** Whether to pay from the balance, with or without `payment_method_id`. */
  use_balance?: boolean;
  /** Whether to pay from eligible credit grants before the balance. */
  use_credits?: boolean;
  return_url?: string;
}

/**
 * As in renewing.
 */
export type RenewalOrderRequestInterval =
  (typeof RenewalOrderRequestInterval)[keyof typeof RenewalOrderRequestInterval];

export const RenewalOrderRequestInterval = {
  day: "day",
  month: "month",
  year: "year",
} as const;

/**
 * The periods and price of the renewal, chosen as in renewing.
 */
export interface RenewalOrderRequest {
  /** Purchase ID saved before submitting. Duplicate creation conflicts; query this order after an unknown result. */
  order_id: string;
  /**
   * As in renewing.
   * @minimum 1
   */
  periods?: number;
  /**
   * As in renewing.
   * @minimum 1
   */
  interval_count?: number;
  /** As in renewing. */
  interval?: RenewalOrderRequestInterval;
}

export interface AutoRenewSet {
  auto_renew: boolean;
}

/**
 * pending_checkout has recorded purchase terms but no confirmed checkout; only a deferred order
 * with an amount due reaches it, since a zero-total order completes checkout at placement.
 * Confirmation moves it to pending. Both pending_checkout
 * and pending can expire or be canceled; neither establishes service delivery.
 *
 * Follows the items. `pending` has confirmed checkout, is not yet accepted and may be paid or unpaid. `active` is
 * accepted with items still being set up. `completed` means every item was set up.
 * `partially_completed` means some items were set up and the others failed or were canceled and were
 * refunded to their original payment sources. `failed` means no item was delivered and at least one failed; collected amounts for the
 * undelivered items are refunded. `canceled` means every item was withdrawn without delivery; collected amounts are
 * returned to their original payment sources.
 */
export type OrderStatus = (typeof OrderStatus)[keyof typeof OrderStatus];

export const OrderStatus = {
  pending_checkout: "pending_checkout",
  pending: "pending",
  active: "active",
  completed: "completed",
  partially_completed: "partially_completed",
  failed: "failed",
  canceled: "canceled",
} as const;

/**
 * `pending` is waiting to be set up. `completed` was confirmed by the service.
 * `failed` was not set up and its amount was refunded to the original payment sources.
 * `canceled` was confirmed withdrawn without delivery; any collected amount is returned. A completed item is ended by canceling
 * its subscription.
 */
export type OrderItemStatus = (typeof OrderItemStatus)[keyof typeof OrderItemStatus];

export const OrderItemStatus = {
  pending: "pending",
  completed: "completed",
  failed: "failed",
  canceled: "canceled",
} as const;

/**
 * `adopt` brings a resource that already existed under billing. It charges nothing at
 * the time and starts billing from the moment agreed.
 */
export type OrderType = (typeof OrderType)[keyof typeof OrderType];

export const OrderType = {
  purchase: "purchase",
  renew: "renew",
  change: "change",
  adopt: "adopt",
} as const;

/**
 * When a plan change takes effect. `none` on anything that is not a change.
 *
 * `period_end` orders stay pending until the first period at the new price is paid. That period
 * is invoiced shortly before the current paid period ends and starts when it ends; if the
 * invoice is still unpaid by then, the order is canceled and the subscription renews or ends as
 * usual. Renewing in the meantime moves all of this along with it.
 */
export type OrderChangeEffective = (typeof OrderChangeEffective)[keyof typeof OrderChangeEffective];

export const OrderChangeEffective = {
  none: "none",
  immediate: "immediate",
  period_end: "period_end",
} as const;

/**
 * Purchase-related invoice amounts, without account contact details or payment methods. A draft
 * order invoice shows base amounts awaiting checkout, not a confirmed discount or collectible total.
 * Absent when no invoice has been created; absence does not establish acceptance or delivery.
 */
export interface InvoiceSummary {
  id: string;
  number?: string;
  currency: string;
  status: InvoiceStatus;
  /**
   * Sum of the line amounts before discounts. Where prices include tax, the tax contained in
   * each line's discounted amount is taken out here, so that total = subtotal -
   * discount_amount + tax_amount always holds.
   */
  subtotal: string;
  /** Sum of the line discounts, taken off before tax. */
  discount_amount: string;
  tax_amount: string;
  total: string;
  amount_paid: string;
  /**
   * What is still collectible after applied credits and successful payments; never below zero.
   * @pattern ^\d+(\.\d{1,10})?$
   */
  amount_due: string;
  amount_refunded: string;
  due_at?: string;
}

export type OrderItemInterval = (typeof OrderItemInterval)[keyof typeof OrderItemInterval];

export const OrderItemInterval = {
  none: "none",
  day: "day",
  month: "month",
  year: "year",
} as const;

/**
 * The payment timing of the selected price.
 */
export type OrderItemBillingType = (typeof OrderItemBillingType)[keyof typeof OrderItemBillingType];

export const OrderItemBillingType = {
  postpaid: "postpaid",
  prepaid: "prepaid",
  one_time: "one_time",
} as const;

export type OrderItemConfiguration = { [key: string]: unknown };

/**
 * Frozen purchase terms. Monetary fields come from related invoice-line snapshots and are absent
 * when there is no immediate invoice. Later catalog changes do not reprice this line. A new service
 * purchase creates its pending subscription when this item is recorded, not when payment succeeds.
 */
export interface OrderItem {
  /** @minimum 0 */
  position?: number;
  configuration?: OrderItemConfiguration;
  /**
   * Stable Billing subscription ID. A new prepaid or postpaid service purchase returns the
   * pending subscription here; renewals and changes reference the existing subscription, which
   * keeps its ID. Absent for delivery without a subscription. This is not a business resource ID.
   */
  subscription_id?: string;
  interval: OrderItemInterval;
  /** @minimum 1 */
  interval_count?: number;
  termination_policy?: TerminationPolicy;
  refund_policy?: RefundPolicy;
  /**
   * Prepaid items only: the plan's one-month prepaid price for this item's quantity before tax, frozen
   * at purchase, used to value time used under a prorated refund or a downgrade. Null when the plan has
   * no prepaid period shorter than the one bought.
   * @nullable
   */
  refund_monthly_amount?: string | null;
  /**
   * Prepaid items only: the plan's postpaid hourly price for this item's quantity before tax, frozen at
   * purchase, used for time used short of a full month. Null when the plan has no postpaid price.
   * @nullable
   */
  refund_hourly_amount?: string | null;
  completes_on_payment: boolean;
  recurring_amount?: string;
  setup_amount?: string;
  /** The payment timing of the selected price. */
  billing_type: OrderItemBillingType;
  /** Total tax after discounts, including any tax already included in the price. */
  tax_amount?: string;
  /** The part of tax_amount already included in gross_amount; it is not charged again. */
  tax_included_amount?: string;
  id: string;
  order_id?: string;
  price_id: string;
  product_id?: ProductID;
  product?: Product;
  /** Which plan was bought. */
  plan_id: string;
  /**
   * What it was called when bought. It does not follow later catalogue renames and is
   * not translated.
   */
  plan_name: string;
  quantity: string;
  /**
   * The unit amount of the price this line is charged under. Absent for a tiered price, which has no
   * single unit amount, and for a change that takes effect at once, which is charged as `gross_amount`
   * describes.
   */
  unit_amount?: Money;
  /**
   * Before discounts: the price applied to the quantity, which for a per-unit price is `unit_amount`
   * times `quantity`; a minimum charge can make it higher. For an upgrade that takes effect at once it is
   * the new price minus the old price for the time left in the paid period, both at the subscription's
   * own period price, and the period end does not move; a downgrade charges nothing and may refund the
   * difference instead. A change between equal period prices charges and refunds nothing. The setup fee is not part of it; see `setup_amount`.
   *
   * Under an inclusive tax rate it includes tax, as the price does, and the included part is
   * `tax_included_amount`. A renewal at the agreed terms is the exception: the agreed amount excludes
   * tax, and tax is added to it.
   */
  gross_amount?: Money;
  /**
   * The reduction on this line: from the coupon the order uses and, for a renewal at the agreed terms,
   * from the discount the subscription carries.
   *
   * A carried discount is part of the agreed amount. It is listed here, and `gross_amount` is then
   * `unit_amount` times `quantity`, except in two cases where `gross_amount` is the agreed amount and
   * the carried discount is already reflected in it: the renewal order also uses a coupon the account
   * holds, or the account's tax rate is inclusive.
   */
  discount_amount?: Money;
  /** `gross_amount` less `discount_amount`. */
  amount?: Money;
  currency: string;
  /** @nullable */
  period_start?: string | null;
  /** @nullable */
  period_end?: string | null;
  status: OrderItemStatus;
}

/**
 * A recorded purchase. pending_checkout requires explicit Billing confirmation before collection
 * or acceptance, even without an invoice. Coupon fields describe a discount confirmed at checkout and are absent
 * before confirmation; a quote never populates them. A draft invoice contains base purchase
 * amounts awaiting checkout. Payment and acceptance remain separate from resource delivery.
 */
export interface Order {
  coupon_id?: string;
  coupon?: ObjectIdentity;
  promotion_code_id?: string;
  /** Code text frozen when checkout applied the coupon. Absent for an account discount. */
  promotion_code?: string;
  invoice?: InvoiceSummary;
  /** How the order was paid. Absent until it is paid. */
  paid_with?: PaidWith;
  account?: AccountIdentity;
  cancel_reason?: string;
  change_effective_at?: string;
  id: string;
  /**
   * Which project it was bought for. Absent for a purchase made at account level, such
   * as a membership.
   * @nullable
   */
  project_id?: string | null;
  /**
   * The project and its current name, for display. Absent for a purchase at account level,
   * and when the project no longer exists or its details cannot be read at the moment;
   * `project_id` still identifies it then.
   */
  project?: NamedIdentity | null;
  /**
   * The billing account the order was placed with. It does not change when the project is later
   * linked to another billing account. While this account is suspended or closed the order cannot
   * be accepted, and a change scheduled for the end of a period is not invoiced and is called off
   * when the current period ends; such requests fail with BILLING_ACCOUNT_UNAVAILABLE.
   */
  billing_account_id?: number;
  currency: string;
  /**
   * `adopt` brings a resource that already existed under billing. It charges nothing at
   * the time and starts billing from the moment agreed.
   */
  type: OrderType;
  status: OrderStatus;
  /**
   * When a plan change takes effect. `none` on anything that is not a change.
   *
   * `period_end` orders stay pending until the first period at the new price is paid. That period
   * is invoiced shortly before the current paid period ends and starts when it ends; if the
   * invoice is still unpaid by then, the order is canceled and the subscription renews or ends as
   * usual. Renewing in the meantime moves all of this along with it.
   */
  change_effective?: OrderChangeEffective;
  /**
   * Acceptance deadline. pending_checkout and pending orders can expire automatically.
   * @nullable
   */
  expires_at?: string | null;
  created_at: string;
  /**
   * What was bought. Present on a single order and on every order in a list, so a list
   * can be rendered without a further request per row.
   */
  items: OrderItem[];
}

export interface OrderList {
  items: Order[];
  pagination: OffsetPagination;
}

